insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992001','$12$','Uma primitiva de $2x+1$ é $x^2+x$. No limite superior, $3^2+3=12$. No limite inferior, a primitiva vale $0$. A diferença entre os valores é $12$. O integrando é positivo em todo o intervalo, o que confirma o sinal da alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
