insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992004','$e^{4x}+C$','Pela regra da cadeia, $d(e^{4x})/dx=4e^{4x}$. Assim, o próprio $e^{4x}$ já tem como derivada o integrando. Somamos a constante arbitrária porque a integral é indefinida. A expressão procurada é $e^{4x}+C$. A verificação por derivação confirma a alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992041','40000000-0000-4000-8000-000000992004','Pela regra da cadeia, $d(e^{4x})/dx=4e^{4x}$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
