insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992083','40000000-0000-4000-8000-000000992008','C','tem negativos',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
