insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992081','40000000-0000-4000-8000-000000992008','Uma condição necessária de convergência deve ser testada antes da alternância.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992082','40000000-0000-4000-8000-000000992008','Calcule o limite do módulo $(n+2)/(n+1)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992083','40000000-0000-4000-8000-000000992008','Sinais alternados não compensam parcelas cuja magnitude permanece próxima de $1$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992008','Os termos não tendem a zero.','O termo geral é $a_n=(-1)^n(n+2)/(n+1)$. Sua magnitude tende a $1$, não a zero. Consequentemente, o próprio termo $a_n$ não possui limite zero. Toda série convergente precisa satisfazer $a_n\to0$. A falha dessa condição prova a divergência indicada em B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992081','40000000-0000-4000-8000-000000992008','O termo geral é $a_n=(-1)^n(n+2)/(n+1)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992082','40000000-0000-4000-8000-000000992008','Sua magnitude tende a $1$, não a zero.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992083','40000000-0000-4000-8000-000000992008','Consequentemente, o próprio termo $a_n$ não possui limite zero.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992084','40000000-0000-4000-8000-000000992008','Toda série convergente precisa satisfazer $a_n\to0$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
