insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992092','40000000-0000-4000-8000-000000992009','O centro é o valor de $x$ que anula a potência.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992093','40000000-0000-4000-8000-000000992009','Não confunda o centro com a razão geométrica ou com o raio.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992009','$-4$','A série contém potências de $x+4=x-(-4)$. Comparando com $\sum c_n(x-a)^n$, identificamos $a=-4$. O divisor $2^n$ influencia o raio, não o centro. Em $x=-4$, todas as parcelas de grau positivo se anulam. Portanto o centro é $-4$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992091','40000000-0000-4000-8000-000000992009','A série contém potências de $x+4=x-(-4)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992092','40000000-0000-4000-8000-000000992009','Comparando com $\sum c_n(x-a)^n$, identificamos $a=-4$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992093','40000000-0000-4000-8000-000000992009','O divisor $2^n$ influencia o raio, não o centro.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992094','40000000-0000-4000-8000-000000992009','Em $x=-4$, todas as parcelas de grau positivo se anulam.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
