insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992010','$-x^2/2$','A expansão é $\cos x=1-x^2/2!+x^4/4!-\cdots$. O termo de grau dois é exatamente $-x^2/2!$. Como $2!=2$, ele se escreve $-x^2/2$. Termos lineares e cúbicos não aparecem na série do cosseno. Assim, a alternativa B identifica o termo pedido.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992101','40000000-0000-4000-8000-000000992010','A expansão é $\cos x=1-x^2/2!+x^4/4!-\cdots$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
