insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992012','$xe^{2x}/2-e^{2x}/4+C$','Tome $u=x$ e $dv=e^{2x}dx$. Então $du=dx$ e $v=e^{2x}/2$. Por partes, a integral vira $xe^{2x}/2-(1/2)\int e^{2x}dx$. A segunda integral vale $e^{2x}/2$, produzindo $xe^{2x}/2-e^{2x}/4+C$. A regra do produto devolve $xe^{2x}$, confirmando A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992121','40000000-0000-4000-8000-000000992012','Tome $u=x$ e $dv=e^{2x}dx$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992122','40000000-0000-4000-8000-000000992012','Então $du=dx$ e $v=e^{2x}/2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992123','40000000-0000-4000-8000-000000992012','Por partes, a integral vira $xe^{2x}/2-(1/2)\int e^{2x}dx$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992124','40000000-0000-4000-8000-000000992012','A segunda integral vale $e^{2x}/2$, produzindo $xe^{2x}/2-e^{2x}/4+C$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
