insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992132','40000000-0000-4000-8000-000000992013','Determine os coeficientes de $A/(x-1)+B/(x+1)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992133','40000000-0000-4000-8000-000000992013','Os logaritmos devem conservar valores absolutos no resultado.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992013','$(3/2)\ln|(x-1)/(x+1)|+C$','Escreva $3/(x^2-1)=A/(x-1)+B/(x+1)$. A identidade $3=A(x+1)+B(x-1)$ dá $A=3/2$ e $B=-3/2$. Integramos cada parcela como um logaritmo. O resultado é $(3/2)[\ln|x-1|-\ln|x+1|]+C$. Reunir os logaritmos produz a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992131','40000000-0000-4000-8000-000000992013','Escreva $3/(x^2-1)=A/(x-1)+B/(x+1)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992132','40000000-0000-4000-8000-000000992013','A identidade $3=A(x+1)+B(x-1)$ dá $A=3/2$ e $B=-3/2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992133','40000000-0000-4000-8000-000000992013','Integramos cada parcela como um logaritmo.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992134','40000000-0000-4000-8000-000000992013','O resultado é $(3/2)[\ln|x-1|-\ln|x+1|]+C$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992135','40000000-0000-4000-8000-000000992013','Reunir os logaritmos produz a alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
