insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992016','Converge.','Para $n\ge1$, temos $n^2+n\ge n^2$. Assim, $0<1/(n^2+n)\le1/n^2$. A série $\sum1/n^2$ converge porque é uma p-série com $p=2$. A comparação direta transfere a convergência para a série dada. Isso justifica especificamente a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992161','40000000-0000-4000-8000-000000992016','Para $n\ge1$, temos $n^2+n\ge n^2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
