insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992017','Condicionalmente convergente.','Os módulos $b_n=1/\sqrt n$ são positivos, decrescentes e tendem a zero. O teste de Leibniz garante convergência da série alternada. A série absoluta é $\sum1/n^{1/2}$. Essa p-série diverge porque $p=1/2\le1$. A classificação final é convergência condicional, como registra B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992171','40000000-0000-4000-8000-000000992017','Os módulos $b_n=1/\sqrt n$ são positivos, decrescentes e tendem a zero.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
