insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992020','$0,18$','O polinômio de grau dois é $P_2(x)=x-x^2/2$. Em $x=0,2$, o termo linear vale $0,2$. O termo quadrático vale $0,04/2=0,02$. Logo $P_2(0,2)=0,2-0,02=0,18$. A alternativa A é a aproximação solicitada.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992201','40000000-0000-4000-8000-000000992020','O polinômio de grau dois é $P_2(x)=x-x^2/2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
