insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992021','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','medium','published','Entre $y=x$ e $y=x^3$ em $[-1,1]$, deve-se separar em zero porque:') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
