insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992211','40000000-0000-4000-8000-000000992021','Área geométrica exige identificar a curva superior em cada subintervalo.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992212','40000000-0000-4000-8000-000000992021','Compare $x$ e $x^3$ à esquerda e à direita de zero.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992213','40000000-0000-4000-8000-000000992021','A troca de ordem ocorre porque o sinal de $x(1-x^2)$ muda.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992021','A curva superior muda em $0$.','As curvas se encontram em $x=-1,0,1$. Em $(0,1)$, $x>x^3$; em $(-1,0)$, $x^3>x$. Uma única diferença manteria sinal errado em metade do intervalo. Por isso a integral da área deve ser separada em $x=0$. A justificativa correta é a mudança da curva superior, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992211','40000000-0000-4000-8000-000000992021','As curvas se encontram em $x=-1,0,1$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992212','40000000-0000-4000-8000-000000992021','Em $(0,1)$, $x>x^3$; em $(-1,0)$, $x^3>x$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992213','40000000-0000-4000-8000-000000992021','Uma única diferença manteria sinal errado em metade do intervalo.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992214','40000000-0000-4000-8000-000000992021','Por isso a integral da área deve ser separada em $x=0$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992215','40000000-0000-4000-8000-000000992021','A justificativa correta é a mudança da curva superior, alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992022','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','medium','published','Calcule $\int_0^1x/\sqrt{1+x^2}dx$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
