insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992223','40000000-0000-4000-8000-000000992022','C','$\sqrt2$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
