insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992221','40000000-0000-4000-8000-000000992022','A expressão sob a raiz tem derivada proporcional ao numerador.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992222','40000000-0000-4000-8000-000000992022','Faça $u=1+x^2$ e converta os limites.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992223','40000000-0000-4000-8000-000000992022','Lembre que $x\,dx=du/2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992022','$\sqrt2-1$','Com $u=1+x^2$, temos $du=2x\,dx$. Os limites $x=0$ e $x=1$ tornam-se $u=1$ e $u=2$. A integral vira $(1/2)\int_1^2u^{-1/2}du$. Sua avaliação é $[\sqrt u]_1^2=\sqrt2-1$. O resultado positivo corresponde à alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992221','40000000-0000-4000-8000-000000992022','Com $u=1+x^2$, temos $du=2x\,dx$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992222','40000000-0000-4000-8000-000000992022','Os limites $x=0$ e $x=1$ tornam-se $u=1$ e $u=2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992223','40000000-0000-4000-8000-000000992022','A integral vira $(1/2)\int_1^2u^{-1/2}du$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992224','40000000-0000-4000-8000-000000992022','Sua avaliação é $[\sqrt u]_1^2=\sqrt2-1$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
