insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992024','$\ln|x|-\ln(x^2+1)/2+C$','A identidade de numeradores fornece $A=1$, $B=-1$ e $C=0$. Assim, o integrando é $1/x-x/(x^2+1)$. As primitivas são $\ln|x|$ e $(1/2)\ln(x^2+1)$. Subtraindo a segunda, obtemos $\ln|x|-(1/2)\ln(x^2+1)+C$. A alternativa A é confirmada pela recomposição.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992241','40000000-0000-4000-8000-000000992024','A identidade de numeradores fornece $A=1$, $B=-1$ e $C=0$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
