insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992243','40000000-0000-4000-8000-000000992024','As primitivas são $\ln|x|$ e $(1/2)\ln(x^2+1)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992244','40000000-0000-4000-8000-000000992024','Subtraindo a segunda, obtemos $\ln|x|-(1/2)\ln(x^2+1)+C$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
