insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992261','40000000-0000-4000-8000-000000992026','A única dificuldade ocorre em $x=1$ e deve ser estudada dos dois lados.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992262','40000000-0000-4000-8000-000000992026','Translade a singularidade com $u=|x-1|$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992263','40000000-0000-4000-8000-000000992026','Use o critério de convergência de $\int_0^1u^{-p}du$, lembrando que o caso-limite é logarítmico.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992026','$p<1$','A simetria em torno de $1$ permite escrever a integral como $2\int_0^1u^{-p}du$. Para $p\ne1$, uma primitiva é $u^{1-p}/(1-p)$. O limite em $u=0^+$ é finito exatamente quando $1-p>0$. Em $p=1$, aparece $\ln u$ e há divergência. Portanto a condição completa é $p<1$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992261','40000000-0000-4000-8000-000000992026','A simetria em torno de $1$ permite escrever a integral como $2\int_0^1u^{-p}du$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992262','40000000-0000-4000-8000-000000992026','Para $p\ne1$, uma primitiva é $u^{1-p}/(1-p)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992263','40000000-0000-4000-8000-000000992026','O limite em $u=0^+$ é finito exatamente quando $1-p>0$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992264','40000000-0000-4000-8000-000000992026','Em $p=1$, aparece $\ln u$ e há divergência.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
