insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992027','Converge pelo teste da razão, com limite $e^{-1}$.','Para $a_n=n!/n^n$, temos $a_{n+1}/a_n=(n/(n+1))^n$. Essa razão se reescreve como $(1+1/n)^{-n}$. Seu limite é $e^{-1}$. Como $e^{-1}<1$, o teste da razão garante convergência absoluta. A conclusão e o limite aparecem juntos na alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992271','40000000-0000-4000-8000-000000992027','Para $a_n=n!/n^n$, temos $a_{n+1}/a_n=(n/(n+1))^n$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992272','40000000-0000-4000-8000-000000992027','Essa razão se reescreve como $(1+1/n)^{-n}$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
