insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992283','40000000-0000-4000-8000-000000992028','Procure o termo não alternado de ordem $1/n$ que permanece após a expansão.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992028','Diverge; há uma componente comparável a $-1/n$.','Escreva $1/(\sqrt n+(-1)^n)=1/\sqrt n-(-1)^n/n+O(n^{-3/2})$. Multiplicando por $(-1)^n$, o termo da série vira $(-1)^n/\sqrt n-1/n+O(n^{-3/2})$. A primeira componente converge pelo teste alternado e o resto de ordem $n^{-3/2}$ é somável. A componente $-1/n$ diverge para $-\infty$ e não pode ser cancelada pelas componentes convergentes. Logo a série diverge pela razão estrutural descrita na alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992281','40000000-0000-4000-8000-000000992028','Escreva $1/(\sqrt n+(-1)^n)=1/\sqrt n-(-1)^n/n+O(n^{-3/2})$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992282','40000000-0000-4000-8000-000000992028','Multiplicando por $(-1)^n$, o termo da série vira $(-1)^n/\sqrt n-1/n+O(n^{-3/2})$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992283','40000000-0000-4000-8000-000000992028','A primeira componente converge pelo teste alternado e o resto de ordem $n^{-3/2}$ é somável.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992284','40000000-0000-4000-8000-000000992028','A componente $-1/n$ diverge para $-\infty$ e não pode ser cancelada pelas componentes convergentes.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992285','40000000-0000-4000-8000-000000992028','Logo a série diverge pela razão estrutural descrita na alternativa C.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
