insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992029','$[-1,3)$','O teste da razão fornece $|x-1|<2$, ou $-1<x<3$. Em $x=-1$, surge $\sum(-1)^n/n$, que converge condicionalmente. Em $x=3$, surge $\sum1/n$, que diverge. Incluímos apenas o extremo esquerdo. O intervalo é $[-1,3)$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
