insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992030','$-31/720$','As contribuições correspondem a $(k,j)=(3,0),(2,1),(1,2),(0,3)$. Seus coeficientes são $1/6$, $-1/4$, $1/24$ e $-1/720$. Somando com denominador $720$, obtemos $(120-180+30-1)/720$. O numerador total é $-31$. Logo o coeficiente pedido é $-31/720$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992301','40000000-0000-4000-8000-000000992030','As contribuições correspondem a $(k,j)=(3,0),(2,1),(1,2),(0,3)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
