insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992323','40000000-0000-4000-8000-000000992032','O termo no infinito tende a zero porque $1-p<0$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992324','40000000-0000-4000-8000-000000992032','No limite inferior, a subtração produz $-1/(1-p)=1/(p-1)$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
